CREATE OR REPLACE VIEW v_appointment_capacity AS SELECT a.service_id,a.appointment_date,COUNT(*) total FROM appointments a WHERE a.status IN ('Pending','Scheduled') GROUP BY a.service_id,a.appointment_date;
